set -e

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
cd "${SCRIPT_DIR}"

SOC_VERSION=""
INSTALL=false
while [[ $# -gt 0 ]]; do
    case $1 in
        --soc=*)
